const OTHER = `Texto de otra tradición`;
function wcfSrc(title, o){ return Object.assign({kind:OTHER, title, date:`1647`, year:1647, ed:ED.wcf, url:LINKS.wcf}, o); }
function bocSrc(title, o){ return Object.assign({kind:OTHER, title, ed:ED.triglot, url:LINKS.boc}, o); }
Object.assign(SRC, {
  WCF281: wcfSrc(`Confesión de Westminster XXVIII.1`, {ex:[
    {es:`El bautismo es un sacramento del Nuevo Testamento, instituido por Jesu-Cristo. no solo para admitir la persona bautizada en la iglesia visible, sino tambien para que sea para ella un signo y sello del concierto de la gracia, del hecho que es ingerida en Cristo, de su regeneracion, de la remision de sus pecados, y de su sumision á Dios por Jesu-Cristo, á fin de andar en novedad de vida. Segun el mismo mandato de Jesu-Cristo, este sacramento debe continuarse en su iglesia hasta el fin del mundo.`, esLv:`wcf`,
     en:`Baptism is a sacrament of the New Testament, ordained by Jesus Christ, not only for the solemn admission of the party baptized into the visible church, but also to be unto him a sign and seal of the covenant of grace, of his ingrafting into Christ, of regeneration, of remission of sins, and of his giving up unto God through Jesus Christ, to walk in newness of life: which sacrament is, by Christ's own appointment, to be continued in his church until the end of the world.`,
     pg:`1894, p. 91; 1880, cap. XXVIII, I, p. 139. Textos de prueba: Mt 28:19; 1 Co 12:13; Ro 4:11 con Col 2:11–12; Gá 3:27; Ro 6:5; Tit 3:5; Mc 1:4; Ro 6:3–4; Mt 28:19–20.`}],
    rv:[`Añadido en el paso de correcciones (crítico 12) para que el objetor defina su propio término; el español de 1880 se leyó en el escaneo de la p. 139. Sin verificador independiente.`]}),
  WCF285: wcfSrc(`Confesión de Westminster XXVIII.5`, {ex:[
    {es:`Aunque el menosprecio ó descuido de esta ordenanza sea un grave pecado, sin embargo, la gracia y la salvacion, no son tan inseparablemente unidas con ella, que seria imposible ser regenerado ó salvo sin ella; y por otra parte, no resulta que todos los que sean bautizados, necesariamente son regenerados.`, esLv:`wcf`,
     en:`Although it be a great sin to contemn or neglect this ordinance, yet grace and salvation are not so inseparably annexed unto it, as that no person can be regenerated or saved without it, or that all that are baptized are undoubtedly regenerated.`,
     pg:`1894, p. 92; 1880, p. 143. Textos de prueba: Lc 7:30 con Éx 4:24–26; Ro 4:11; Hch 10:2, 4, 22, 31, 45, 47; Hch 8:13, 23.`}],
    rv:[`Texto actual: la OPC imprime hoy la misma redacción.`]}),
  WCF286: wcfSrc(`Confesión de Westminster XXVIII.6`, {ex:[
    {es:`La eficácia del bautismo no se limita al momento mismo en que se administra; sin embargo, por el propio uso de esta ordenanza, la gracia prometida no solamente se ofrece, sino realmente es en debido tiempo demostrada y dada por el Espíritu Santo, á aquellos (sean adultos ó párvulos) á quienes pertenece aquella gracia, segun el consejo de la propia voluntad de Dios.`, esLv:`wcf`,
     en:`The efficacy of baptism is not tied to that moment of time wherein it is administered; yet notwithstanding, by the right use of this ordinance, the grace promised is not only offered, but really exhibited and conferred by the Holy Ghost, to such (whether of age or infants) as that grace belongeth unto, according to the counsel of God's own will, in his appointed time.`,
     pg:`1894, p. 92; 1880, p. 144. Textos de prueba: Jn 3:5, 8; Gá 3:27; Tit 3:5; Ef 5:25–26; Hch 2:38, 41.`}],
    rv:[`«es en debido tiempo demostrada y» se leyó en el escaneo de la p. 144 (verificación D1).`]}),
  WLC161: wcfSrc(`Catecismo Mayor de Westminster, pregunta 161`, {ex:[
    {es:`Los sacramentos llegan a ser medios eficaces de salvación no por algún poder que haya en ellos, ni por alguna virtud que proceda de la piedad o de la intención de quien los administra, sino solo por la obra del Espíritu Santo y la bendición de Cristo, que los instituyó.`, esLv:`ia`, esFrom:`desde el inglés`,
     en:`The sacraments become effectual means of salvation, not by any power in themselves, or any virtue derived from the piety or intention of him by whom they are administered, but only by the working of the Holy Ghost, and the blessing of Christ, by whom they are instituted.`,
     pg:`1894, p. 200. Textos de prueba: 1 P 3:21; Hch 8:13 con 8:23; 1 Co 3:6–7; 1 Co 12:13.`}]}),
  WLC165: wcfSrc(`Catecismo Mayor de Westminster, pregunta 165`, {ex:[
    {es:`El bautismo es un sacramento del Nuevo Testamento, en el cual Cristo ha ordenado el lavamiento con agua en el nombre del Padre, y del Hijo, y del Espíritu Santo, para que sea signo y sello de la incorporación a él, de la remisión de los pecados por su sangre y de la regeneración por su Espíritu; de la adopción y de la resurrección para la vida eterna; y por el cual los bautizados son admitidos solemnemente en la iglesia visible y entran en un compromiso abierto y declarado de ser total y únicamente del Señor.`, esLv:`ia`, esFrom:`desde el inglés`,
     en:`Baptism is a sacrament of the New Testament, wherein Christ hath ordained the washing with water in the name of the Father, and of the Son, and of the Holy Ghost, to be a sign and seal of ingrafting into himself, of remission of sins by his blood, and regeneration by his Spirit; of adoption, and resurrection unto everlasting life; and whereby the parties baptized are solemnly admitted into the visible church, and enter into an open and professed engagement to be wholly and only the Lord's.`,
     pg:`1894, p. 201`}],
    rv:[RV_APPLY]}),
  WCF273: wcfSrc(`Confesión de Westminster XXVII.3`, {ex:[
    {es:`La gracia que se comunica en los sacramentos, ó por ellos dignamente empleados, no se dá por ningun poder que está en ellos, ni depende la eficácia de un sacramento de la piedad ó intencion de aquel que lo administra, sino de la operacion del Espíritu, y de las palabras de institucion, que contienen, juntamente con el precepto que autoriza el uso del sacramento, una promesa de bendicion para los que lo reciban dignamente.`, esLv:`wcf`,
     en:`The grace which is exhibited in or by the sacraments, rightly used, is not conferred by any power in them; neither doth the efficacy of a sacrament depend upon the piety or intention of him that doth administer it, but upon the work of the Spirit, and the word of institution; which contains, together with a precept authorizing the use thereof, a promise of benefit to worthy receivers.`,
     pg:`1894, p. 90; 1880, p. 137. Textos de prueba: Ro 2:28–29; 1 P 3:21; Mt 3:11; 1 Co 12:13; Mt 26:27–28; 28:19–20.`}]}),
  WCF274: wcfSrc(`Confesión de Westminster XXVII.4`, {ex:[
    {es:`No hay sino dos sacramentos ordenados en el Evangelio por nuestro Señor Jesu-Cristo, á saber, el bautismo y la Cena del Señor; ni el uno, ni el otro de los cuales debe administrarse, sino por un ministro de la palabra legalmente ordenado.`, esLv:`wcf`,
     en:`There be only two sacraments ordained by Christ our Lord in the gospel, that is to say, Baptism, and the Supper of the Lord; neither of which may be dispensed by any but by a minister of the word, lawfully ordained.`,
     pg:`1894, p. 90; 1880, p. 138. Textos de prueba: Mt 28:19; 1 Co 11:20, 23; 1 Co 4:1; Heb 5:4.`}],
    rv:[`Frase positiva en forma exclusiva, sin nombrar a nadie: la misma gramática que Fe y Mensaje Bautistas VII (OB-7, Pregunta 2).`]}),
  WCF282: wcfSrc(`Confesión de Westminster XXVIII.2`, {ex:[
    {es:`«por un ministro del evangelio debidamente autorizado»`, esLv:`wcf`,
     en:`The outward element to be used in this sacrament is water, wherewith the party is to be baptized in the name of the Father, and of the Son, and of the Holy Ghost, by a minister of the gospel, lawfully called thereunto.`,
     pg:`1894, p. 91; 1880, p. 140. Textos de prueba: Mt 3:11; Jn 1:33; Mt 28:19–20.`}],
    rv:[`El dosier solo transcribe este fragmento del español de 1880.`]}),
  WCF65: wcfSrc(`Confesión de Westminster VI.5`, {ex:[
    {es:`Esta corrupcion de la naturaleza existe durante esta vida, aun en aquellos que sean regenerados; y aunque sea perdonada y amortiguada por médio de la fé en Cristo, sin embargo, ella, y todos los efectos de ella, son verdadera y propiamente pecado.`, esLv:`wcf`,
     en:`This corruption of nature, during this life, doth remain in those that are regenerated; and although it be through Christ pardoned and mortified, yet both itself, and all the motions thereof, are truly and properly sin.`,
     pg:`1894, p. 34. Textos de prueba (notas de 1880): Ro 7:14, 17, 18, 23 …`}],
    rv:[`Leído en la ejecución de Justificación.`]}),
  AC13: bocSrc(`Confesión de Augsburgo XIII (Del uso de los sacramentos)`, {url:LINKS.trig, ex:[
    {la:`De usu sacramentorum docent, quod sacramenta instituta sint, non modo ut sint notae professionis inter homines, sed magis ut sint signa et testimonia voluntatis Dei erga nos, ad excitandam et confirmandam fidem in his, qui utuntur, proposita. Itaque utendum est sacramentis ita, ut fides accedat, quae credat promissionibus, quae per sacramenta exhibentur et ostenduntur. Damnant igitur illos, qui docent, quod sacramenta ex opere operato iustificent, nec docent fidem requiri in usu sacramentorum, quae credat remitti peccata.`,
     es:`Sobre el uso de los sacramentos enseñan que los sacramentos fueron instituidos no solo para ser señales de profesión entre los hombres, sino más bien para ser signos y testimonios de la voluntad de Dios hacia nosotros, propuestos para despertar y confirmar la fe en quienes los usan. Por eso hay que usar los sacramentos de modo que se añada la fe, que crea las promesas que por los sacramentos se ofrecen y muestran. Condenan, por tanto, a quienes enseñan que los sacramentos justifican ex opere operato y no enseñan que en el uso de los sacramentos se requiere la fe que cree que los pecados son perdonados.`, esLv:`ia`, esFrom:`desde el latín`,
     en:`Of the Use of the Sacraments they teach that the Sacraments were ordained, not only to be marks of profession among men, but rather to be signs and testimonies of the will of God toward us, instituted to awaken and confirm faith in those who use them. … They therefore condemn those who teach that the Sacraments justify by the outward act, and who do not teach that, in the use of the Sacraments, faith which believes that sins are forgiven, is required.`,
     pg:`Triglot 1921, p. 48`}]}),
  AP13: bocSrc(`Apología de la Confesión de Augsburgo XIII (VII), 18–20, 23`, {url:LINKS.trig, ex:[
    {la:`Illud magis est necessarium intelligere, quomodo sit utendum sacramentis. Hic damnamus totum populum scholasticorum doctorum, qui docent, quod sacramenta non ponenti obicem conferant gratiam ex opere operato sine bono motu utentis. Haec simpliciter Iudaica opinio est sentire, quod per ceremoniam iustificemur, sine bono motu cordis, hoc est, sine fide.`,
     es:`Es más necesario entender cómo se han de usar los sacramentos. Aquí condenamos a toda la multitud de doctores escolásticos que enseñan que los sacramentos confieren la gracia ex opere operato a quien no pone obstáculo, sin un buen movimiento de quien los usa. Esta es sencillamente una opinión judía: pensar que somos justificados por una ceremonia, sin un buen movimiento del corazón, es decir, sin fe. […] Pablo lo contradice y niega (Romanos 4:9) que Abraham fuera justificado por la circuncisión […] La promesa es inútil si no se recibe por la fe.`, esLv:`ia`, esFrom:`(¶18 desde el latín; el resto desde el inglés: rehacer desde el latín)`,
     en:`Here we condemn the whole crowd of scholastic doctors, who teach that the Sacraments confer grace ex opere operato, without a good disposition on the part of the one using them, provided he do not place a hindrance in the way. This is absolutely a Jewish opinion, to hold that we are justified by a ceremony, without a good disposition of the heart, i.e., without faith. And yet this impious and pernicious opinion is taught with great authority throughout the entire realm of the Pope. Paul contradicts this, and denies, Rom. 4:9, that Abraham was justified by circumcision, but asserts that circumcision was a sign presented for exercising faith. Thus we teach that in the use of the Sacraments faith ought to be added, which should believe these promises … The promise is useless unless it is received by faith.`,
     pg:`¶18 latín: Triglot 1921, p. 312`},
    {en:`no one can express in words what abuses in the Church this fanatical opinion concerning the opus operatum, without a good disposition on the part of the one using the Sacraments, has produced.`, pg:`¶23. Sin español en el dosier.`}],
    rv:[`Lenguaje duro con estado actual («Iudaica opinio», «throughout the entire realm of the Pope»): Pregunta 16.`]}),
  LC433: bocSrc(`Catecismo Mayor IV.33 (Del bautismo)`, {ex:[
    {es:`solo la fe hace a la persona digna de recibir con provecho el agua salvadora y divina. Porque, como estos bienes se presentan y prometen aquí en las palabras, en el agua y con ella, no pueden recibirse de otro modo que creyéndolos de corazón.`, esLv:`ia`, esFrom:`desde el inglés (rehacer desde el alemán)`,
     en:`faith alone makes the person worthy to receive profitably the saving, divine water. For, since these blessings are here presented and promised in the words in and with the water, they cannot be received in any other way than by believing them with the heart.`}],
    rv:[`Añadido en el paso de correcciones, para equilibrar Catecismo 1127 en la respuesta. ${RV_APPLY}`]}),
  LC473: bocSrc(`Catecismo Mayor IV.73`, {url:LINKS.trig, ex:[
    {la:`Iam ubicunque fides fructibus fecunda viget, hic baptismus non tantum inanem significationem repraesentat, sed mortificandae carnis opera coniuncta habet. Porro autem absente fide nudum et inefficax signum tantummodo permanet.`,
     es:`Donde la fe florece con sus frutos, este bautismo no representa una significación vacía, sino que lleva unidas las obras de mortificar la carne. Pero, ausente la fe, permanece solo como signo desnudo e ineficaz.`, esLv:`ia`, esFrom:`desde el latín`,
     en:`Where, therefore, faith flourishes with its fruits, there it has no empty signification, but the work [of mortifying the flesh] accompanies it; but where faith is wanting, it remains a mere unfruitful sign.`,
     pg:`Triglot 1921, p. 750 (escaneo)`}],
    rv:[`Añadido en el paso de correcciones. ${RV_APPLY}`]}),
  LC480: bocSrc(`Catecismo Mayor IV.80–82`, {url:LINKS.trig, ex:[
    {de:`Das sage ich darum, daß man nicht in die Meinung komme, darin wir lange Zeit gewesen sind und gewähnt haben, die Taufe wäre nun hin [mit der Taufe wäre es nun vorbei] […] Und ist zwar daher [ge]kommen, daß St. Hieronymus geschrieben hat: „Die Buße sei die andere Tafel [tabula, Brett], damit wir müssen [her]ausschwimmen und [hin]überkommen, nachdem das Schiff gebrochen ist, darein wir treten und [hin]überfahren, wenn wir in die Christenheit kommen." Damit ist nun der [Ge-]Brauch der Taufe weggenommen, daß sie uns nicht mehr nützen kann. Darum ist's nicht recht geredet oder je nicht recht verstanden; denn das Schiff zerbricht nicht, weil es (wie gesagt) Gottes Ordnung und nicht unser Ding ist`,
     es:`Digo esto para que no caigamos en la opinión en que estuvimos mucho tiempo, creyendo que el bautismo ya había pasado […] Y esto vino de que san Jerónimo escribió: "La penitencia es la segunda tabla con la que, roto el barco, tenemos que nadar y pasar al otro lado". Con eso se quitó el uso del bautismo, de modo que ya no puede servirnos. Por eso no está bien dicho, o al menos no bien entendido; porque el barco no se rompe, ya que es ordenación de Dios y no cosa nuestra`, esLv:`ia`, esFrom:`desde el alemán`,
     en:`This I say lest we fall into the opinion in which we were for a long time, imagining that our Baptism is something past, which we can no longer use after we have fallen again into sin. … And this arose from the fact that St. Jerome wrote that repentance is the second plank by which we must swim forth and cross over after the ship is broken … Therefore the statement is not correct, or at any rate not rightly understood. For the ship never breaks, because (as we have said) it is the ordinance of God, and not a work of ours; but it happens, indeed, that we slip and fall out of the ship.`,
     pg:`Alemán: Triglot 1921, p. 750 (escaneo); los corchetes son de los editores`}],
    rv:[`Alemán re-tomado de la impresión de 1921 en el paso de correcciones. ${RV_APPLY}`]}),
  LC474: bocSrc(`Catecismo Mayor IV.74–79, 86`, {ex:[
    {en:`Baptism, both in its power and signification, comprehends also the third Sacrament, which has been called repentance, as it is really nothing else than Baptism. (74–75) … Therefore our Baptism abides forever; and even though some one should fall from it and sin, nevertheless we always have access thereto (77) … Repentance, therefore, is nothing else than a return and approach to Baptism (79) … But if any one fall away from it, let him again come into it. (86)`, pg:`Sin español en el dosier.`}]}),
  LC465: bocSrc(`Catecismo Mayor IV.65`, {ex:[
    {es:`una vida verdaderamente cristiana no es otra cosa que un bautismo diario, comenzado una vez y continuado siempre`, esLv:`ia`, esFrom:`desde el inglés (rehacer desde el alemán)`,
     en:`a truly Christian life is nothing else than a daily baptism, once begun and ever to be continued.`}],
    rv:[`Añadido en el paso de correcciones, para equilibrar Catecismo 977 y 980 en la respuesta. ${RV_APPLY}`]}),
  AP134: bocSrc(`Apología de la Confesión de Augsburgo XIII.4`, {ex:[
    {en:`Baptism, the Lord's Supper, and Absolution, which is the Sacrament of Repentance, are truly Sacraments`, pg:`Sin español en el dosier.`}]}),
  AP2: bocSrc(`Apología de la Confesión de Augsburgo II (I), 35, 38–39`, {ex:[
    {es:`El bautismo quita la culpa del pecado original, aunque permanece lo que llaman la materia del pecado, es decir, la concupiscencia. […] Pero ellos sostienen que la concupiscencia es una pena y no un pecado […] Lutero sostiene que es pecado.`, esLv:`ia`, esFrom:`desde el inglés (rehacer desde el latín)`,
     en:`Baptism removes the guilt of original sin, although the material, as they call it, of the sin, i.e., concupiscence, remains. … But they contend that concupiscence is a penalty, and not a sin … Luther maintains that it is a sin. … Besides Paul says, Rom. 7:7. 23: I had not known lust (concupiscence), except the Law had said, Thou shalt not covet.`}],
    rv:[`Tomado del dosier de Justificación (OB-3); no releído aquí.`]}),
  ENC8: {kind:OTHER, title:`Encíclica patriarcal y sinodal de 1895, §VIII`, date:`1895`, year:1895, ed:ED.enc1895, url:LINKS.enc, ex:[
    {es:`La una, santa, católica y apostólica Iglesia de los siete primeros concilios ecuménicos bautizaba con tres inmersiones en el agua; el papa Pelagio habla de la triple inmersión como mandato del Señor, y en el siglo XIII todavía prevalecía en Occidente el bautismo por inmersiones; las mismas pilas sagradas que se conservan en las iglesias más antiguas de Italia son testigos elocuentes de ello. Pero más tarde la aspersión o la infusión, introducidas a escondidas, fueron aceptadas por la Iglesia papal, que todavía mantiene la innovación, ensanchando así el abismo que ella misma abrió; pero nosotros, los ortodoxos, fieles a la tradición apostólica y a la práctica de los siete concilios ecuménicos, "nos mantenemos firmes, luchando por la profesión común, el tesoro paterno de la fe sana"`, esLv:`ia`, esFrom:`desde el inglés de Metallinos (rehacer desde el griego)`,
     en:`The one holy, catholic and apostolic Church of the first seven Oecumenical Councils baptized by three immersions in the water, and the Pope Pelagius speaks of the triple immersion as a command of the Lord, and in the thirteenth century baptism by immersions still prevailed in the West; and the sacred fonts themselves, preserved in the more ancient churches in Italy, are eloquent witnesses on this point; but in later times sprinkling or affusion, being privily brought in, came to be accepted by the Papal Church, which still holds fast the innovation, thus also widening the gulf which she has opened; but we Orthodox, remaining faithful to the apostolic tradition and the practice of the seven Oecumenical Councils, 'stand fast, contending for the common profession, the paternal treasure of the sound faith.'`,
     pg:`1896, p. 31. Las palabras finales citan a Basilio, Ep. 243`}],
    rv:[`Cláusula final del español añadida en el paso de correcciones (crítico 15).`, `Lenguaje duro y estado actual («Iglesia papal … innovación»): Pregunta 16; el estado actual del texto de 1895 no está comprobado.`]},
  ENC46: {kind:OTHER, title:`Encíclica patriarcal y sinodal de 1895, §IV y §VI`, date:`1895`, year:1895, ed:ED.enc1895, url:LINKS.enc, ex:[
    {en:`there is an evident contradiction when in one and the same Church … one sprinkles, and another baptizes (immerses) thrice in the water`, pg:`§IV, p. 21. Sin español en el dosier.`},
    {en:`sprinkling instead of baptism`, pg:`§VI, p. 25: entre las doctrinas que Occidente debe probar que se sostenían «before the ninth century». Sin español en el dosier.`}]},
  MOG102: {kind:OTHER, title:`Pedro Mogila, Confesión ortodoxa I, preguntas 102–103`, ed:ED.mogila, url:LINKS.mogila, ex:[
    {es:`El bautismo es un lavar y arrancar el pecado original, siendo sumergido tres veces en el agua, mientras el sacerdote pronuncia estas palabras: En el nombre del Padre, amén; y del Hijo, amén; y del Espíritu Santo, amén.`, esLv:`ia`, esFrom:`desde el inglés de 1762 (rehacer desde el griego)`,
     en:`Baptism is a washing away and rooting out of original Sin, by being thrice immersed in Water; the Priest pronouncing these Words: In The Name Of The Father, Amen; And Of The Son, Amen; And Of The Holy Ghost, Amen.`, pg:`Pregunta 102`},
    {en:`being observant to use the proper Requisite, namely, unmixed and natural and pure Water, and dipping the Person to be baptized thrice therein`, pg:`Pregunta 103: en caso de necesidad cualquiera puede bautizar. Sin español en el dosier.`}],
    rv:[`Añadido en el paso de correcciones (crítico 21). ${RV_APPLY}`]},
  MOG102r: {kind:OTHER, title:`Pedro Mogila, Confesión ortodoxa I, pregunta 102 (sobre no repetir el bautismo)`, ed:ED.mogila, url:LINKS.mogila, ex:[
    {es:`una vez recibido, este misterio no se repite, con tal que quien administró el bautismo creyera ortodoxamente en tres Personas en un solo Dios y pronunciara con exactitud y sin alteración alguna las palabras dichas`, esLv:`ia`, esFrom:`desde el inglés de 1762 (rehacer desde el griego)`,
     en:`being once received, is not to be again repeated; provided the Person who administered the Baptism believed orthodoxly in Three Persons in One God, and accurately, and without any Alteration, pronounced the afore-mentioned Words`, pg:`Overbeck, p. 76`}],
    rv:[RV_APPLY]},
  PHIL290: {kind:OTHER, title:`Filareto, Catecismo extenso, pregunta 290`, ed:ED.schaff, ex:[
    {en:`What is most essential in the administration of Baptism? Trine immersion in water, in the name of the Father, and of the Son, and of the Holy Ghost.`, pg:`Sin español en el dosier.`}],
    rv:[`El dosier lo da como la propia afirmación de la tradición, para contexto.`]},
  OROSa: {kind:OTHER, title:`Oros de Constantinopla (1755/56), sobre el modo`, date:`1755/56`, year:1755, ed:ED.oros, url:LINKS.oros, ex:[
    {es:`seguimos a los sagrados y divinos Apóstoles, que mandan bautizar a los aspirantes con tres inmersiones y emersiones, diciendo en cada inmersión uno de los nombres de la Santísima Trinidad`, esLv:`ia`, esFrom:`desde el inglés (rehacer desde el griego de Mansi 38)`,
     en:`we follow the sacred and divine Apostles who order us to baptize aspirants with three immersions and emersions, and in each immersion to say one name of the Holy Trinity`}]},
  OROSb: {kind:OTHER, title:`Oros de Constantinopla (1755/56), sobre el bautismo de los herejes`, date:`1755/56`, year:1755, ed:ED.oros, url:LINKS.oros, ex:[
    {es:`Nosotros, que por la misericordia divina fuimos criados en la Iglesia ortodoxa y nos atenemos a los cánones de los sagrados Apóstoles y de los divinos Padres, reconocemos una sola Iglesia, nuestra santa, católica y apostólica Iglesia. Son sus misterios [es decir, sacramentos], y por tanto su bautismo, los que aceptamos.`, esLv:`ia`, esFrom:`desde el inglés (rehacer desde el griego de Mansi 38)`,
     en:`We, who by divine mercy were raised in the Orthodox Church, and who adhere to the canons of the sacred Apostles and divine Fathers, recognize only one Church, our holy, catholic, and Apostolic Church. It is her Mysteries [i.e. sacraments], and consequently her baptism, that we accept.`},
    {es:`Rechazamos y aborrecemos los bautismos de los herejes. Porque discrepan del divino mandato apostólico y le son ajenos. Son aguas inútiles, como dijeron san Ambrosio y san Atanasio el Grande. No dan santificación a quienes los reciben, ni sirven en nada para lavar los pecados. A los que vienen a la fe ortodoxa, bautizados sin haber sido bautizados, los recibimos como no bautizados`, esLv:`ia`, esFrom:`desde el inglés (rehacer desde el griego de Mansi 38)`,
     en:`we reject and abhor baptisms belonging to heretics. For they disagree with and are alien to the divine Apostolic dictate. They are useless waters, as Sts. Ambrose and Athanasios the Great said. They give no sanctification to such as receive them, nor avail at all to the washing away of sins. We receive those who come over to the Orthodox faith, who were baptized without being baptized, as being unbaptized`}],
    rv:[`Frases eclesiales añadidas en el paso de correcciones (experto 2). ${RV_APPLY}`, `«aguas inútiles» se muestra como palabras del Oros, no de Ambrosio ni de Atanasio (DECISIONS 2026-10-15).`]},
  DOS16: {kind:OTHER, title:`Dositeo, Confesión (Jerusalén, 1672), decreto XVI`, date:`1672`, year:1672, ed:ED.robertson, url:LINKS.robertson, ex:[
    {es:`lo administra solo el sacerdote o, en caso de necesidad ineludible, otro hombre, con tal que sea ortodoxo y tenga la intención propia del divino bautismo`, esLv:`ia`, esFrom:`desde el inglés (rehacer desde el griego)`,
     en:`is performed by the Priest only, or in a case of unavoidable necessity, by another man, provided he be Orthodox, and have the intention proper to Divine Baptism`, pg:`Robertson, p. 141`}],
    rv:[RV_APPLY]},
  DOS15: {kind:OTHER, title:`Dositeo, Confesión (Jerusalén, 1672), decreto XV`, date:`1672`, year:1672, ed:ED.robertson, url:LINKS.robertson, ex:[
    {es:`rechazamos como cosa abominable y perniciosa la idea de que, cuando la fe es débil, se menoscaba la integridad del misterio. Porque los herejes que abjuran de su herejía y se unen a la Iglesia católica son recibidos por la Iglesia, aunque recibieron su bautismo válido con debilidad de fe. Por eso, cuando después llegan a tener la fe perfecta, no se los bautiza de nuevo.`, esLv:`ia`, esFrom:`desde el inglés (rehacer desde el griego)`,
     en:`we reject as something abominable and pernicious the notion that when faith is weak the integrity of the Mystery is impaired. For heretics who abjure their heresy and join the Catholic Church are received by the Church; although they received their valid Baptism with weakness of faith. Wherefore, when they afterwards become possessed of the perfect faith, they are not again baptised.`, pg:`Robertson, pp. 138–139`}],
    rv:[`Del otro lado, dentro de la misma tradición: Dositeo recibe el «bautismo válido» de los herejes. Primera frase añadida en el paso de correcciones (crítico 13).`]},
  BFM7: {kind:OTHER, title:`Fe y Mensaje Bautistas (2000), art. VII`, date:`2000`, year:2000, ed:ED.bfm, url:LINKS.bfmEs, ex:[
    {es:`El bautismo cristiano es la inmersión de un creyente en agua en el nombre del Padre, del Hijo, y del Espíritu Santo. Es un acto de obediencia que simboliza la fe del creyente en un Salvador crucificado, sepultado y resucitado, la muerte del creyente al pecado, la sepultura de la antigua vida, y la resurrección para andar en novedad de vida en Cristo Jesús. Es un testimonio de su fe en la resurrección final de los muertos. Como es una ordenanza de la iglesia, es un requisito que precede al privilegio de ser miembro de la iglesia y a participar en la Cena del Señor.`, esLv:`sbc`,
     en:`Christian baptism is the immersion of a believer in water in the name of the Father, the Son, and the Holy Spirit. It is an act of obedience symbolizing the believer's faith in a crucified, buried, and risen Saviour, the believer's death to sin, the burial of the old life, and the resurrection to walk in newness of life in Christ Jesus. It is a testimony to his faith in the final resurrection of the dead. Being a church ordinance, it is prerequisite to the privileges of church membership and to the Lord's Supper.`,
     pg:`Textos de prueba: Mt 3:13–17; 26:26–30; 28:19–20; Mc 1:9–11; 14:22–26; Lc 3:21–22; 22:19–20; Jn 3:23; Hch 2:41–42; 8:35–39; 16:30–33; 20:7; Ro 6:3–5; 1 Co 10:16, 21; 11:23–29; Col 2:12.`}],
    rv:[`Español oficial de la SBC, en lugar de la traducción por IA del primer borrador (crítico 17). ${RV_APPLY}`]},
  BFM6: {kind:OTHER, title:`Fe y Mensaje Bautistas (2000), art. VI, primera frase`, date:`2000`, year:2000, ed:ED.bfm, url:LINKS.bfmEs, ex:[
    {es:`Una iglesia del Nuevo Testamento del Señor Jesucristo es una congregación local y autónoma de creyentes bautizados, asociados en un pacto en la fe y el compañerismo del evangelio; cumpliendo las dos ordenanzas de Cristo`, esLv:`sbc`,
     en:`A New Testament church of the Lord Jesus Christ is an autonomous local congregation of baptized believers, associated by covenant in the faith and fellowship of the gospel; observing the two ordinances of Christ`}],
    rv:[`Añadido en el paso de correcciones, para equilibrar Catecismo 1231. La enmienda de 2023 del art. VI (sobre los oficios) no afecta esta frase. ${RV_APPLY}`]},
  AG6a: {kind:OTHER, title:`Asambleas de Dios, Declaración de Verdades Fundamentales, art. 6a`, ed:ED.ag, url:LINKS.agEs, ex:[
    {es:`Las Escrituras establecen la ordenanza del bautismo en agua por inmersión. Todos los que se arrepienten y creen en Cristo como Salvador y Señor deben ser bautizados. De esta manera declaran ante el mundo que han muerto con Cristo y que han sido resucitados con El para andar en nueva vida.`, esLv:`ag`,
     en:`The ordinance of baptism by immersion is commanded by the Scriptures. All who repent and believe on Christ as Saviour and Lord are to be baptized. Thus they declare to the world that they have died with Christ and that they also have been raised with Him to walk in newness of life.`,
     pg:`Textos de prueba: Mt 28:19; Mc 16:16; Hch 10:47–48; Ro 6:4.`}],
    rv:[`Cuenta solo para el modo: «All who repent and believe … are to be baptized» enuncia una condición suficiente, no exclusiva. Que las capturas de Wayback conserven el contenido de su fecha no está confirmado.`]}
});

